// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetHealthz The process is up
	// (GET /healthz)
	GetHealthz(ctx context.Context, request GetHealthzRequestObject) (GetHealthzResponseObject, error)
	// GetReadyz The process can reach the ratings database
	// (GET /readyz)
	GetReadyz(ctx context.Context, request GetReadyzRequestObject) (GetReadyzResponseObject, error)
	// GetCurrentRun The run the site shows now
	// (GET /v1/runs/current)
	GetCurrentRun(ctx context.Context, request GetCurrentRunRequestObject) (GetCurrentRunResponseObject, error)
	// GetActivity Who plays, and where
	// (GET /v1/runs/{run}/analysis/activity)
	GetActivity(ctx context.Context, request GetActivityRequestObject) (GetActivityResponseObject, error)
	// GetAgreement How far the models agree
	// (GET /v1/runs/{run}/analysis/agreement)
	GetAgreement(ctx context.Context, request GetAgreementRequestObject) (GetAgreementResponseObject, error)
	// GetCalibration How well each model predicted games
	// (GET /v1/runs/{run}/analysis/calibration)
	GetCalibration(ctx context.Context, request GetCalibrationRequestObject) (GetCalibrationResponseObject, error)
	// GetDistribution How ratings spread in each engine
	// (GET /v1/runs/{run}/analysis/distribution)
	GetDistribution(ctx context.Context, request GetDistributionRequestObject) (GetDistributionResponseObject, error)
	// GetComparedPlayers Players across every model
	// (GET /v1/runs/{run}/analysis/players)
	GetComparedPlayers(ctx context.Context, request GetComparedPlayersRequestObject) (GetComparedPlayersResponseObject, error)
	// GetCatalogue Every tournament with games
	// (GET /v1/runs/{run}/catalogue)
	GetCatalogue(ctx context.Context, request GetCatalogueRequestObject) (GetCatalogueResponseObject, error)
	// GetCatalogueTournament One tournament's seasons, stages and podiums
	// (GET /v1/runs/{run}/catalogue/{tournament})
	GetCatalogueTournament(ctx context.Context, request GetCatalogueTournamentRequestObject) (GetCatalogueTournamentResponseObject, error)
	// GetCommunityLeaderboard An edition of the community leaderboard
	// (GET /v1/runs/{run}/community/{edition})
	GetCommunityLeaderboard(ctx context.Context, request GetCommunityLeaderboardRequestObject) (GetCommunityLeaderboardResponseObject, error)
	// GetHistory Each player's rating at a past date, for rating changes over time
	// (GET /v1/runs/{run}/history)
	GetHistory(ctx context.Context, request GetHistoryRequestObject) (GetHistoryResponseObject, error)
	// GetLeaderboard Every rated player in one model and format, in rank order
	// (GET /v1/runs/{run}/leaderboard)
	GetLeaderboard(ctx context.Context, request GetLeaderboardRequestObject) (GetLeaderboardResponseObject, error)
	// GetLeaderboardCsv The leaderboard as a CSV file, filtered and sorted as the site's table
	// (GET /v1/runs/{run}/leaderboard.csv)
	GetLeaderboardCsv(ctx context.Context, request GetLeaderboardCsvRequestObject) (GetLeaderboardCsvResponseObject, error)
	// GetPlayer One player's ratings in every model and format, for the player page
	// (GET /v1/runs/{run}/players/{name})
	GetPlayer(ctx context.Context, request GetPlayerRequestObject) (GetPlayerResponseObject, error)
	// GetPlayerAchievements One player's tournament achievements, for their achievements page
	// (GET /v1/runs/{run}/players/{name}/achievements)
	GetPlayerAchievements(ctx context.Context, request GetPlayerAchievementsRequestObject) (GetPlayerAchievementsResponseObject, error)
	// GetPlayerCareer One player's record each year and each model's peak, for the career box
	// (GET /v1/runs/{run}/players/{name}/career)
	GetPlayerCareer(ctx context.Context, request GetPlayerCareerRequestObject) (GetPlayerCareerResponseObject, error)
	// GetPlayerHistory One player's rating at the end of every period, for the chart
	// (GET /v1/runs/{run}/players/{name}/history)
	GetPlayerHistory(ctx context.Context, request GetPlayerHistoryRequestObject) (GetPlayerHistoryResponseObject, error)
	// GetPlayerMatches One player's games, newest first, 30 to a page
	// (GET /v1/runs/{run}/players/{name}/matches)
	GetPlayerMatches(ctx context.Context, request GetPlayerMatchesRequestObject) (GetPlayerMatchesResponseObject, error)
	// GetPlayerMatrix One player's rating in each engine and reset mode, now or at a year's end
	// (GET /v1/runs/{run}/players/{name}/matrix)
	GetPlayerMatrix(ctx context.Context, request GetPlayerMatrixRequestObject) (GetPlayerMatrixResponseObject, error)
	// GetPlayerRivals The player's record against each opponent
	// (GET /v1/runs/{run}/players/{name}/rivals)
	GetPlayerRivals(ctx context.Context, request GetPlayerRivalsRequestObject) (GetPlayerRivalsResponseObject, error)
	// GetPlayerVersus The latest games two players played together
	// (GET /v1/runs/{run}/players/{name}/versus/{other})
	GetPlayerVersus(ctx context.Context, request GetPlayerVersusRequestObject) (GetPlayerVersusResponseObject, error)
	// GetHallOfFame The Hall of Fame overview
	// (GET /v1/runs/{run}/tournaments)
	GetHallOfFame(ctx context.Context, request GetHallOfFameRequestObject) (GetHallOfFameResponseObject, error)
	// GetTournamentSeries A tournament series' Hall of Fame page
	// (GET /v1/runs/{run}/tournaments/{series})
	GetTournamentSeries(ctx context.Context, request GetTournamentSeriesRequestObject) (GetTournamentSeriesResponseObject, error)
	// GetYears The years a run's ratings cover, newest first, for the season archive
	// (GET /v1/runs/{run}/years)
	GetYears(ctx context.Context, request GetYearsRequestObject) (GetYearsResponseObject, error)
	// GetYearLeaderboard The ratings at the end of a year, for the season archive
	// (GET /v1/runs/{run}/years/{year}/leaderboard)
	GetYearLeaderboard(ctx context.Context, request GetYearLeaderboardRequestObject) (GetYearLeaderboardResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// GetHealthz operation middleware
